export function validateCT_Textbox(value: unknown, path = 'CT_Textbox'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (v['txbxContent'] === undefined) {
    issues.push(issue(path + '.txbxContent', 'missing-required', 'required slot is absent'));
  } else {
    issues.push(...validateCT_TxbxContent(v['txbxContent'], path + '.txbxContent'));
  }
  if (v['id'] === undefined) {
  } else {
    if (!validBuiltin(v['id'], 'xsd:string')) issues.push(issue(path + '.id', 'invalid-value', 'invalid xsd:string'));
  }
  if (v['style'] === undefined) {
  } else {
    if (!validBuiltin(v['style'], 'xsd:string')) issues.push(issue(path + '.style', 'invalid-value', 'invalid xsd:string'));
  }
  if (v['inset'] === undefined) {
  } else {
    if (!validBuiltin(v['inset'], 'xsd:string')) issues.push(issue(path + '.inset', 'invalid-value', 'invalid xsd:string'));
  }
  if (v['singleclick'] === undefined) {
  } else {
    issues.push(...validateST_TrueFalse(v['singleclick'], path + '.singleclick'));
  }
  if (v['insetmode'] === undefined) {
  } else {
    issues.push(...validateST_InsetMode(v['insetmode'], path + '.insetmode'));
  }
  return issues;
}
